  "implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    pair_distance = {}
    for u, v, d in distances:
        key = (min(u, v), max(u, v))
        pair_distance[key] = d

    edges = []
    for (u, v), d in pair_distance.items():
        mr = max(core_distance[u], core_distance[v], d)
        edges.append((mr, u, v))

    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == len(nodes) - 1:
                break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Disconnected graph")

    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
